                    report.append(f"  {opt['description']}")

            if low_priority:
                report.append(f"\n### Low Priority ({len(low_priority)})")
                for opt in low_priority:
                    report.append(f"  • {opt['description']}")

        report.append("\n" + "=" * 70)

        return "\n".join(report)


